assert set(P.keys()) == set(EXPECTED), (set(EXPECTED) ^ set(P.keys()))
assert len(P) == 40

sizes = {}
for cid in EXPECTED:
    rec = {"case_id": cid, "prediction_text": P[cid]["prediction_text"], "basis": P[cid]["basis"],
           "confidence": P[cid]["confidence"], "trigger": P[cid]["trigger"]}
    path = os.path.join(BASE, cid + ".json")
    with open(path, "w", encoding="utf-8") as f:
        json.dump(rec, f, ensure_ascii=False, indent=1)
    sizes[cid] = os.path.getsize(path)

# per-case readback verification (exact id list only, no glob)
cm = ru = di = 0
for cid in EXPECTED:
    with open(os.path.join(BASE, cid + ".json"), encoding="utf-8") as f:
        r = json.load(f)
    assert r["case_id"] == cid and r["prediction_text"] and r["basis"] and 0 <= r["confidence"] <= 1
    t = r["trigger"]
    assert set(t.keys()) == {"changed_main", "reserve_used", "disputed", "reason"}
    cm += bool(t["changed_main"]); ru += bool(t["reserve_used"]); di += bool(t["disputed"])

print("cases:", len(EXPECTED), "written:", len(sizes), "total_bytes:", sum(sizes.values()))
print("trigger counts: changed_main=%d reserve_used=%d disputed=%d" % (cm, ru, di))
print("sizes:", sizes)
